// "Led by" / "Supported by" — who may join a bodyguard unit, per faction (generated by
// scripts/gen-roster-data.mjs's genLedBy; see the note there). Lazy and per faction, like the
// roster bundles: a datasheet page loads its own faction's ~6 KB and nothing else.
const loaders = import.meta.glob(['./*.js', '!./index.js', '!./*.test.js'], { import: 'default' })
const cache = new Map()

export function loadLedBy(slug) {
  const load = loaders[`./${slug}.js`]
  if (!load) return Promise.resolve(null)
  if (!cache.has(slug)) cache.set(slug, load())
  return cache.get(slug)
}
